INSERT INTO products VALUES(2,6,'เสื้อยืดแขนสั้น Cotton 100%','cotton-t-shirt','เสื้อยืดแขนสั้นผลิตจากผ้า Cotton 100% สวมใส่สบาย ระบายอากาศได้ดี ดีไซน์มินิมอลเหมาะสำหรับทุกวัน',350,49,'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=500&auto=format&fit=crop&q=60',1,'2026-09-22 14:01:09','2026-09-22 14:15:44');
