INSERT INTO products VALUES(4,8,'แชมพูสูตรขจัดรังแค 450ml','anti-dandruff-shampoo-450ml','แชมพูสูตรพิเศษช่วยขจัดรังแคอย่างมีประสิทธิภาพ บำรุงหนังศีรษะให้ชุ่มชื้น ลดอาการคัน ผมนุ่มสลวย',159,45,'https://images.unsplash.com/photo-1535585209827-a15fcdbc4c2d?w=500&auto=format&fit=crop&q=60',1,'2026-09-22 14:01:09','2026-09-22 14:01:09');
INSERT INTO products VALUES(5,7,'กระดาษทิชชู่ เช็ดหน้า (แพ็ค 3 ห่อ)','facial-tissue-3pack','กระดาษเช็ดหน้าเนื้อเนียนนุ่มพิเศษ ซึมซับดีเยี่ยม ไม่เป็นขุย ไร้สารเรืองแสง อ่อนโยนต่อทุกสภาพผิว',79,120,'https://images.unsplash.com/photo-1584556812952-905ffd0c611a?w=500&auto=format&fit=crop&q=60',1,'2026-09-22 14:01:09','2026-09-22 14:01:09');
