INSERT INTO products VALUES(7,10,'แก้วน้ำเก็บความเย็น สแตนเลส 30 oz','stainless-tumbler-30oz','แก้วเก็บความเย็น-ร้อน สแตนเลส 304 ขนาด 30 oz เก็บความเย็นได้นานถึง 18 ชั่วโมง ไม่มีหยดน้ำเกาะรอบแก้ว พกพาสะดวก',290,60,'https://images.unsplash.com/photo-1577741314755-048d8525d31e?w=500&auto=format&fit=crop&q=60',1,'2026-09-22 14:01:09','2026-09-22 14:01:09');
